public void verifyCode(UUID requestId, String code) {
  var v = props.verification();
  String codeKey = CODE_KEY_PREFIX + requestId;
  String stored = redis.opsForValue().get(codeKey);
  if (stored == null) throw ApiException.badRequest("Код истёк или не был отправлен");
  String attemptsKey = ATTEMPTS_KEY_PREFIX + requestId;
  Long attempts = redis.opsForValue().increment(attemptsKey);
  if (attempts != null && attempts == 1) redis.expire(attemptsKey, v.codeTtl());
  if (attempts != null && attempts > v.maxAttempts()) { redis.delete(codeKey); redis.delete(attemptsKey); throw ApiException.tooManyRequests("Превышено число попыток. Запросите новый код"); }
  int sep = stored.indexOf(':');
  String salt = stored.substring(0, sep); String hash = stored.substring(sep+1);
  if (!Hashing.constantTimeEquals(hash, Hashing.sha256Hex(salt + code))) throw ApiException.badRequest("Неверный код подтверждения");
  redis.delete(codeKey); redis.delete(attemptsKey);
}
```
